import fs from 'node:fs';
import path from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { buildSkillPackage } from './packages/core/src/domain/skill-package.ts';
import { validatePackage } from './packages/core/src/application/validate-package.ts';
const root = path.resolve('skills/repository-pattern');
const paths = [];
function walk(dir) { for (const entry of fs.readdirSync(dir, {withFileTypes:true})) { const absolute = path.join(dir,entry.name); if(entry.isDirectory()) walk(absolute); else paths.push(absolute); } }
walk(root);
const files = paths.map(absolute=>({path:path.relative(root,absolute).split(path.sep).join('/'),bytes:fs.readFileSync(absolute)}));
const parsed = parseManifest(fs.readFileSync(path.join(root,'skill.yaml'),'utf8'),{strict:true,source:'skills/repository-pattern/skill.yaml'});
const pkg = buildSkillPackage(parsed.manifest,files);
const report = validatePackage(pkg,{directoryName:'repository-pattern'});
const brokenLinks = [];
let linksChecked = 0;
for (const file of files.filter(file=>file.path.endsWith('.md'))) {
 for (const match of Buffer.from(file.bytes).toString('utf8').matchAll(/\[[^\]]*\]\((<[^>]*>|[^)]+)\)/g)) {
  const destination = match[1].startsWith('<') ? match[1].slice(1,-1) : match[1];
  const target = destination.split('#')[0];
  if(!target || /^[a-z][a-z0-9+.-]*:/i.test(target)) continue;
  linksChecked++;
  if(!fs.existsSync(path.resolve(root,path.dirname(file.path),target))) brokenLinks.push({from:file.path,target});
 }
}
const issues = [...parsed.issues,...report.issues];
console.log(JSON.stringify({runtime:process.version,skill:parsed.manifest.name,version:parsed.manifest.version,files:files.map(f=>f.path),issues,linksChecked,brokenLinks},null,2));
if(issues.length || brokenLinks.length) process.exitCode=1;

