import java.util.UUID;
import org.springframework.data.jpa.repository.JpaRepository;

interface Customers extends JpaRepository<Customer, UUID> {
    boolean existsByEmailKey(String emailKey);
}

files.src/Registration.java:
import java.util.UUID;
import org.springframework.transaction.support.TransactionTemplate;

final class Registration {
    enum Result { CREATED, DUPLICATE }
    private final Customers customers;
    private final TransactionTemplate transactions;
    Registration(Customers customers, TransactionTemplate transactions) {
        this.customers = customers; this.transactions = transactions;
    }
    Result register(String emailKey) {
        try {
            return transactions.execute(status -> {
                if (customers.existsByEmailKey(emailKey)) return Result.DUPLICATE;
                customers.save(new Customer(UUID.randomUUID(), emailKey));
                return Result.CREATED;
            });
        } catch (RuntimeException failure) {
            if (PostgreSqlFailures.isDuplicateEmail(failure)) return Result.DUPLICATE;
            throw failure;
        }
    }
}

